body:
Taking the suggested example from the PR, the original binding for the `IntersectRay` looks like this(I have inlined the native calls for clarity):

```csharp
[DebuggerBrowsable(DebuggerBrowsableState.Never)]
private static readonly IntPtr MethodBind1 = ClassDB_get_method_with_compatibility(NativeName, MethodName.IntersectRay, 3957970750ul);

public unsafe Godot.Collections.Dictionary IntersectRay(PhysicsRayQueryParameters3D parameters)
{
    IntPtr ptr = GodotObject.GetPtr(this);
    IntPtr arg1 = GodotObject.GetPtr(parameters);
    ExceptionUtils.ThrowIfNullPtr(ptr);
    godot_dictionary ret = default;
    void** call_args = stackalloc void*[1] { &arg1 };
    NativeFuncs.godotsharp_method_bind_ptrcall(MethodBind1, ptr, call_args, &ret);
    return Godot.Collections.Dictionary.CreateTakingOwnershipOfDisposableValue(ret);
}
```

In the last line, we construct a `Dictionary` using the `CreateTakingOwnershipOfDisposableValue` method. This allocates a new `Dictionary` wrapper object, which causes the GC allocations.

I propose to generate an additional method that directly marshals the contents of the `godot_dictionary` struct into a generated struct, so no new wrapper object is created.

```csharp
public record struct IntersectRayResult(
    Vector3 Position,
    Vector3 Normal,
    long FaceIndex,
    long ColliderId,
    GodotObject Collider,
    long Shape,
    Rid Rid
)
{
    internal static readonly Variant PositionKey = "position";
    internal static readonly Variant NormalKey = "normal";
    internal static readonly Variant FaceIndexKey = "face_index";
    internal static readonly Variant ColliderIdKey = "collider_id";
    internal static readonly Variant ColliderKey = "collider";
    internal static readonly Variant ShapeKey = "shape";
    internal static readonly Variant RidKey = "rid";
}

public unsafe IntersectRayResult? IntersectRayNonAlloc(PhysicsRayQueryParameters3D parameters)
{
    IntPtr ptr = GodotObject.GetPtr(this);
    IntPtr arg1 = GodotObject.GetPtr(parameters);
    ExceptionUtils.ThrowIfNullPtr(ptr);
    godot_dictionary ret = default;
    void** call_args = stackalloc void*[1] { &arg1 };
    NativeFuncs.godotsharp_method_bind_ptrcall(MethodBind1, ptr, call_args, &ret);
    if (NativeFuncs.godotsharp_dictionary_count(ref ret) == 0) return null;

    // Let's ignore checks for now
    NativeFuncs.godotsharp_dictionary_try_get_value(ref ret, (godot_variant)IntersectRayResult.PositionKey.NativeVar, out godot_variant positionValue);
    NativeFuncs.godotsharp_dictionary_try_get_value(ref ret, (godot_variant)IntersectRayResult.NormalKey.NativeVar, out godot_variant normalValue);
    NativeFuncs.godotsharp_dictionary_try_get_value(ref ret, (godot_variant)IntersectRayResult.FaceIndexKey.NativeVar, out godot_variant faceIndexValue);
    NativeFuncs.godotsharp_dictionary_try_get_value(ref ret, (godot_variant)IntersectRayResult.ColliderIdKey.NativeVar, out godot_variant colliderIdValue);
    NativeFuncs.godotsharp_dictionary_try_get_value(ref ret, (godot_variant)IntersectRayResult.ColliderKey.NativeVar, out godot_variant colliderValue);
    NativeFuncs.godotsharp_dictionary_try_get_value(ref ret, (godot_variant)IntersectRayResult.ShapeKey.NativeVar, out godot_variant shapeValue);
    NativeFuncs.godotsharp_dictionary_try_get_value(ref ret, (godot_variant)IntersectRayResult.RidKey.NativeVar, out godot_variant ridValue);

    return new IntersectRayResult(
        positionValue.Vector3,
        normalValue.Vector3,
        faceIndexValue.Int,
        colliderIdValue.Int,
        // Or use VariantUtils for all types?
        VariantUtils.ConvertToGodotObject(colliderValue),
        shapeValue.Int,
        ridValue.Rid
    );
}
```
